#!/bin/bash
set -eo pipefail
umask 077
exec timeout --signal=TERM --kill-after=5s 85s /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_VEGETATION_NUMERICAL_DEPLOY'
import base64,hashlib,io,json,pathlib,re,shutil,subprocess,sys,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/vegetation_numerical_v2')
assert root.parent.resolve(strict=True)==root.parent and not root.exists() and not root.is_symlink()
assert shutil.disk_usage(root.parent).free>=2*1024**3
packed=base64.b64decode('',validate=True)
assert len(packed)==28444 and hashlib.sha256(packed).hexdigest()=='590404cf6ea1c69918c9cc07eaa9edc17217098812b87a9020518b774525c622'
table=json.loads('{"main/vegetation_numerical_main_v2.py":{"bytes":18123,"sha256":"b7f0c08004a28d9cbad0b7f946f6dddc1dd2be2564308433738fa330fbd2d406"},"independent/vegetation_numerical_independent_v2.py":{"bytes":22084,"sha256":"1f3fd04509d28538ad1760b8daff5b390b2c17ab93679c8dac984c70c00887db"},"vegetation_numerical_control_v2.py":{"bytes":8001,"sha256":"9d23fc89d37cbb1096500c6f926e084b1c77a714d6075ed3cd9993cb42bd7634"},"main/VEGETATION_NUMERICAL_CONTRACT.json":{"bytes":25756,"sha256":"1f5a8009cf507e8e48862c4d954d894be5523c4ece4d4b240e042af4855cad13"},"independent/VEGETATION_NUMERICAL_CONTRACT.json":{"bytes":25866,"sha256":"b65985d0f91cc3c98b841cf57a3691ee60e019ea7e1d2cfddb27b3a39624fb57"},"VEGETATION_CONTROL_CONTRACT.json":{"bytes":905,"sha256":"0dcfd43070b4349fafaa3f47a0da6ebf042c9a283baec55fe31d2ddd69ad07a0"},"ADAPTER_DECISION_RECORD.json":{"bytes":5469,"sha256":"36e4d38ca29bd4fb652a74d6c8e48e209ec311e67212010d19e94c3467719527"},"vegetation.sbatch":{"bytes":846,"sha256":"3450d2b09af34eb14ddad351d02f0e313096028a30d4f5b01b07ecffb9c12fc7"},"ENTRY_TABLE.json":{"bytes":1191,"sha256":"67a4d7c1243865aa45cc1630a975fbc6ed7ee925bec81081dfdb8e78b076f7a7"}}')
root.mkdir(mode=0o700)
(root/'logs').mkdir(mode=0o700)
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 assert archive.namelist()==sorted(table) and len(archive.namelist())==len(set(archive.namelist()))
 assert sum(item.file_size for item in archive.infolist())<=1048576
 for name in archive.namelist():
  parts=pathlib.PurePosixPath(name).parts
  assert 1<=len(parts)<=2 and all(p not in ('','.','..') for p in parts) and not name.startswith('/')
  raw=archive.read(name)
  assert len(raw)==table[name]['bytes'] and hashlib.sha256(raw).hexdigest()==table[name]['sha256']
  target=root/name
  target.parent.mkdir(exist_ok=True)
  with target.open('xb') as stream:stream.write(raw)
print('OWN_VEGETATION_NUMERICAL_PAYLOAD_VERIFIED='+str(len(table)),flush=True)
with (root/'SUBMISSION_STARTED.json').open('x') as stream:json.dump(dict(attempt=1,new_source_gets=0,
 scientific_arrays_on_login=0,model_calls=0,automatic_retries=0),stream)
result=dict(exit_code=None,status='SUBMISSION_UNKNOWN_NO_RETRY',stdout='',stderr='')
try:
 outcome=subprocess.run(['sbatch',str(root/'vegetation.sbatch')],capture_output=True,timeout=30)
 result.update(exit_code=outcome.returncode,stdout=outcome.stdout[:65536].decode('utf8','replace'),
               stderr=outcome.stderr[:65536].decode('utf8','replace'),
               stdout_bytes=len(outcome.stdout),stderr_bytes=len(outcome.stderr),
               stdout_sha256=hashlib.sha256(outcome.stdout).hexdigest(),
               stderr_sha256=hashlib.sha256(outcome.stderr).hexdigest())
 assert len(outcome.stdout)<=65536 and len(outcome.stderr)<=65536
 jobs=re.findall(r'^Submitted batch job ([0-9]+)$',result['stdout'],re.M)
 assert outcome.returncode==0 and len(jobs)==1
 with (root/'OWN_VEGETATION_NUMERICAL_JOB_ID').open('x') as stream:stream.write(jobs[0]+'\n')
 result.update(status='UNIQUE_JOB_SUBMITTED',job_id=jobs[0])
except Exception as error:
 result.update(error_type=type(error).__name__,error=str(error))
 if isinstance(error,subprocess.TimeoutExpired):
  for label in ('stdout','stderr'):
   partial=getattr(error,label,None) or b''
   result[label]=partial[:65536].decode('utf8','replace')
   result[label+'_bytes']=len(partial)
   result[label+'_sha256']=hashlib.sha256(partial).hexdigest()
with (root/'SUBMISSION_RESULT.json').open('x') as stream:json.dump(result,stream,indent=2)
print(result['stdout'],end='')
print(result['stderr'],end='')
if result['status']!='UNIQUE_JOB_SUBMITTED':
 print('OWN_VEGETATION_NUMERICAL_SUBMISSION_UNKNOWN_NO_RETRY')
 sys.exit(1)
print('OWN_VEGETATION_NUMERICAL_JOB_ID='+result['job_id'])
print('OWN_VEGETATION_NUMERICAL_SUBMIT_DONE')
PY_VEGETATION_NUMERICAL_DEPLOY
